(function(){
"use strict";
var canvas=document.getElementById('game'), ctx=canvas.getContext('2d');
var scoreEl=document.getElementById('score'), bestEl=document.getElementById('best');
var hintEl=document.getElementById('hint');
var startScreen=document.getElementById('startScreen'), pauseScreen=document.getElementById('pauseScreen'), overScreen=document.getElementById('overScreen');
var W=0,H=0,DPR=1;

function resize(){
  DPR=Math.min(window.devicePixelRatio||1,2);
  W=window.innerWidth; H=window.innerHeight;
  canvas.width=Math.round(W*DPR); canvas.height=Math.round(H*DPR);
  ctx.setTransform(DPR,0,0,DPR,0,0);
  layoutBed();
}
window.addEventListener('resize',resize);

/* ============ AUDIO — WebAudio, all sounds synthesized, none skipped ============ */
var AC=null, soundOn=true;
/* ============ REAL SOUNDS - sliced from the original video ============ */
var SFX={ready:false};
function sfxInit(){
  if(SFX.ready) return; SFX.ready=true;
  SFX.bounce=[new Audio('data:audio/mpeg;base64,'),new Audio('data:audio/mpeg;base64,'),new Audio('data:audio/mpeg;base64,')];
  SFX.splat=new Audio('data:audio/mpeg;base64,');
  SFX.gameover=new Audio('data:audio/mpeg;base64,');
  SFX.all=SFX.bounce.concat([SFX.splat,SFX.gameover]);
  for(var i=0;i<SFX.all.length;i++){ SFX.all[i].preload='auto'; }
}
var sfxPrimed=false;
function sfxPrime(){
  sfxInit(); if(sfxPrimed) return; sfxPrimed=true;
  for(var i=0;i<SFX.all.length;i++){ (function(a){ a.muted=true; var pr=a.play(); if(pr&&pr.then) pr.then(function(){ a.pause(); a.currentTime=0; a.muted=false; }).catch(function(){ a.muted=false; }); })(SFX.all[i]); }
}
function playSfx(a){
  if(!soundOn||!a) return false;
  try{ a.currentTime=0; var pr=a.play(); if(pr&&pr.catch) pr.catch(function(){}); return true; }catch(e){ return false; }
}

function audio(){
  if(!AC){ try{ AC=new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} }
  if(AC && AC.state==='suspended'){ AC.resume(); }
  sfxPrime();
  return AC;
}
function tone(freqA,freqB,dur,type,vol,when){
  if(!soundOn) return; var ac=audio(); if(!ac) return;
  var t=ac.currentTime+(when||0);
  var o=ac.createOscillator(), g=ac.createGain();
  o.type=type||'sine';
  o.frequency.setValueAtTime(freqA,t);
  o.frequency.exponentialRampToValueAtTime(Math.max(freqB,1),t+dur);
  g.gain.setValueAtTime(0.0001,t);
  g.gain.exponentialRampToValueAtTime(vol||0.25,t+0.015);
  g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
  o.connect(g); g.connect(ac.destination);
  o.start(t); o.stop(t+dur+0.05);
}
function noiseBurst(dur,vol,freq,when){
  if(!soundOn) return; var ac=audio(); if(!ac) return;
  var t=ac.currentTime+(when||0);
  var len=Math.floor(ac.sampleRate*dur);
  var buf=ac.createBuffer(1,len,ac.sampleRate), d=buf.getChannelData(0);
  for(var i=0;i<len;i++){ d[i]=(Math.random()*2-1)*(1-i/len); }
  var src=ac.createBufferSource(); src.buffer=buf;
  var f=ac.createBiquadFilter(); f.type='lowpass'; f.frequency.value=freq||800;
  var g=ac.createGain(); g.gain.value=vol||0.4;
  src.connect(f); f.connect(g); g.connect(ac.destination);
  src.start(t);
}
/* BOING on bounce — springy pitch sweep up, with a little wobble */
function sndBoing(power){
  sfxInit(); if(SFX.bounce && playSfx(SFX.bounce[(Math.random()*SFX.bounce.length)|0])) return;
  var base=180+Math.min(power||0,14)*14;
  tone(base,base*2.6,0.28,'sine',0.32,0);
  tone(base*1.5,base*3.1,0.2,'triangle',0.14,0.02);
  tone(90,240,0.12,'square',0.05,0);
}
/* POP / stretch while dragging fast — tiny tick */
function sndTick(){ tone(500,700,0.05,'triangle',0.05,0); }
/* SPLAT on miss — wet thud: noise burst + low drop */
function sndSplat(){
  sfxInit(); if(playSfx(SFX.splat)) return;
  noiseBurst(0.3,0.5,700,0);
  noiseBurst(0.18,0.3,1600,0.01);
  tone(320,45,0.32,'sine',0.4,0);
  tone(180,40,0.25,'triangle',0.25,0.03);
}
/* GAME OVER jingle — descending wah-wah-wah-waaah */
function sndGameOver(){
  sfxInit(); if(playSfx(SFX.gameover)) return;
  var notes=[392,370,349,311];
  for(var i=0;i<notes.length;i++){
    tone(notes[i],notes[i]*0.94, i===3?0.65:0.22,'triangle',0.26, 0.28+i*0.24);
    tone(notes[i]/2,notes[i]/2*0.94, i===3?0.65:0.22,'sine',0.12, 0.28+i*0.24);
  }
}
/* little cheer arpeggio on new best */
function sndBest(){
  var n=[523,659,784,1047];
  for(var i=0;i<n.length;i++) tone(n[i],n[i],0.16,'triangle',0.2,i*0.09);
}

/* ============ FACES ============ */
var faceImg=null; // uploaded photo
var EMOJIS=['😲','😱','🤪','😵','🙃','😬','🥴','😆'];
var SLEEPER='😴';
/* ============ VIDEO FACES - cropped from the original video ============ */
function mkImg(s){ var i=new Image(); i.src=s; return i; }
var VID_SLEEPER=mkImg('data:image/png;base64,');
var VID_FALLERS=[mkImg('data:image/png;base64,'),mkImg('data:image/png;base64,')];

function drawFace(x,y,r,emoji,rot,img){
  ctx.save(); ctx.translate(x,y); ctx.rotate(rot||0);
  var im=faceImg||img;
  if(im && im.complete && im.naturalWidth>0){
    ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.closePath(); ctx.clip();
    ctx.drawImage(im,-r,-r,r*2,r*2);
    ctx.restore();
    ctx.save(); ctx.translate(x,y);
    ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2);
    ctx.lineWidth=2; ctx.strokeStyle='rgba(0,0,0,.55)'; ctx.stroke();
  }else{
    ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2);
    ctx.fillStyle='#ffd94d'; ctx.fill();
    ctx.lineWidth=2; ctx.strokeStyle='rgba(0,0,0,.5)'; ctx.stroke();
    ctx.font=(r*1.25)+'px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(emoji,0,r*0.08);
  }
  ctx.restore();
}

/* ============ BED ============ */
var bed={x:0,w:280,h:64,topY:0, vx:0, squash:0, targetX:0};
function bedWidth(){ return Math.max(210, Math.min(W*0.62, 330)); }
function layoutBed(){
  bed.w=bedWidth();
  bed.topY=H-92; // mattress top
  if(bed.x===0){ bed.x=W/2; bed.targetX=W/2; }
  bed.x=Math.max(bed.w/2, Math.min(W-bed.w/2, bed.x));
  bed.targetX=Math.max(bed.w/2, Math.min(W-bed.w/2, bed.targetX));
}
function drawBed(){
  var w=bed.w, left=bed.x-w/2, top=bed.topY;
  var sq=bed.squash; // squash on bounce
  var mh=30+sq*10;   // mattress height
  ctx.save();
  /* legs */
  ctx.fillStyle='#3a2c20';
  ctx.fillRect(left+10, top+mh+16, 9, 16);
  ctx.fillRect(left+w-19, top+mh+16, 9, 16);
  /* headboard — brown wood, left */
  ctx.fillStyle='#8a5a33';
  roundRect(left-6, top-56, 30, mh+34, 6); ctx.fill();
  ctx.fillStyle='#a06a3a';
  roundRect(left-1, top-50, 20, mh+22, 4); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,.35)'; ctx.lineWidth=2;
  roundRect(left-6, top-56, 30, mh+34, 6); ctx.stroke();
  /* bed base / frame */
  ctx.fillStyle='#6e6e6e';
  roundRect(left, top+mh-2, w, 18, 3); ctx.fill();
  /* mattress — light */
  ctx.fillStyle='#e9e4d6';
  roundRect(left, top, w, mh, 6); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,.4)'; ctx.lineWidth=2;
  roundRect(left, top, w, mh, 6); ctx.stroke();
  /* blanket — dark green, from pillow to right end */
  var bx=left+58;
  ctx.fillStyle='#1e4d3a';
  roundRect(bx, top+3, w-(bx-left)-2, mh+8, 6); ctx.fill();
  ctx.fillStyle='#276149';
  roundRect(bx, top+3, w-(bx-left)-2, 9, 5); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,.35)'; ctx.lineWidth=1.5;
  roundRect(bx, top+3, w-(bx-left)-2, mh+8, 6); ctx.stroke();
  /* pillow — white, left end */
  ctx.fillStyle='#ffffff';
  roundRect(left+8, top-12, 56, 26, 9); ctx.fill();
  ctx.strokeStyle='rgba(0,0,0,.3)'; ctx.lineWidth=1.5;
  roundRect(left+8, top-12, 56, 26, 9); ctx.stroke();
  /* sleeper face on the pillow */
  drawFace(left+36, top+1, 19, SLEEPER, -0.06, VID_SLEEPER);
  /* sleeper's stick legs poking out at the right end of the blanket */
  var lx=left+w-6, ly=top+mh-2;
  ctx.strokeStyle='#111'; ctx.lineWidth=3; ctx.lineCap='round';
  ctx.beginPath();
  ctx.moveTo(lx-16, ly-4); ctx.lineTo(lx+8, ly-12); ctx.lineTo(lx+16, ly-10);
  ctx.moveTo(lx-14, ly+2); ctx.lineTo(lx+10, ly+2); ctx.lineTo(lx+18, ly+5);
  ctx.stroke();
  ctx.restore();
}
function roundRect(x,y,w,h,r){
  r=Math.min(r,w/2,h/2);
  ctx.beginPath();
  ctx.moveTo(x+r,y);
  ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r);
  ctx.closePath();
}

/* ============ FALLER (stick figure) ============ */
var faller=null;
var particles=[];
var splatMark=null;
function spawnFaller(){
  var margin=50;
  faller={
    x: margin+Math.random()*(W-margin*2),
    y:-50, vy:0, vx:(Math.random()-0.5)*0.6,
    rot:0, vr:(Math.random()-0.5)*0.02,
    phase:Math.random()*Math.PI*2,
    emoji: EMOJIS[Math.floor(Math.random()*EMOJIS.length)],
    vface: VID_FALLERS[Math.floor(Math.random()*VID_FALLERS.length)],
    state:'falling', r:24
  };
}
function drawStick(f){
  var t=performance.now()/90 + f.phase*10;
  var flail = f.state==='falling' ? 1 : 0.4;
  var a1=Math.sin(t)*0.7*flail, a2=Math.cos(t*1.13)*0.7*flail;
  var l1=Math.sin(t*1.31)*0.8*flail, l2=Math.cos(t*0.91)*0.8*flail;
  var fx=f.x, fy=f.y;
  var neckY=fy+f.r*0.85, hipY=neckY+26;
  ctx.save();
  ctx.strokeStyle='#111'; ctx.lineWidth=3.4; ctx.lineCap='round'; ctx.lineJoin='round';
  ctx.beginPath();
  /* torso */
  ctx.moveTo(fx,neckY); ctx.lineTo(fx,hipY);
  /* arms flailing */
  ctx.moveTo(fx,neckY+5);
  ctx.lineTo(fx+Math.cos(a1)*24, neckY+5+Math.sin(a1)*24);
  ctx.moveTo(fx,neckY+5);
  ctx.lineTo(fx-Math.cos(a2)*24, neckY+5+Math.sin(a2)*24);
  /* legs kicking */
  ctx.moveTo(fx,hipY);
  ctx.lineTo(fx+Math.sin(l1)*22, hipY+24);
  ctx.moveTo(fx,hipY);
  ctx.lineTo(fx-Math.sin(l2)*22, hipY+24);
  ctx.stroke();
  ctx.restore();
  drawFace(fx,fy,f.r,f.emoji,f.rot,f.vface);
  return hipY+24; // feet Y
}

/* ============ GAME STATE ============ */
var state='menu'; // menu | playing | paused | over
var score=0, best=0, frame=0, shake=0, flashRed=0;
var newBestFlag=false;

function setScore(v){
  score=v; scoreEl.textContent=v;
  if(v>best){ best=v; bestEl.textContent='BEST '+best; if(state==='playing'&&v>1) newBestFlag=true; }
}
function startGame(){
  audio();
  setScore(0); bestEl.textContent='BEST '+best;
  particles=[]; splatMark=null; shake=0; flashRed=0;
  bed.x=W/2; bed.targetX=W/2; bed.squash=0;
  spawnFaller();
  state='playing';
  startScreen.classList.add('hidden'); overScreen.classList.add('hidden'); pauseScreen.classList.add('hidden');
  hintEl.style.opacity='1';
  setTimeout(function(){ hintEl.style.opacity='0'; },2600);
}
function gameOver(){
  state='over';
  sndSplat();
  setTimeout(sndGameOver, 260);
  if(newBestFlag){ setTimeout(sndBest, 1500); }
  document.getElementById('finalScore').textContent=score;
  document.getElementById('finalBest').textContent='BEST '+best;
  var msgs=['He missed the bed…','So close! The floor is not soft.','The sleeper didn\'t even wake up. 😴','Gravity wins this round.','Ouch. Right on the floorboards.'];
  document.getElementById('overMsg').textContent = newBestFlag ? '🎉 New best score!' : msgs[Math.floor(Math.random()*msgs.length)];
  newBestFlag=false;
  setTimeout(function(){ overScreen.classList.remove('hidden'); },650);
}
function bounceOff(){
  var f=faller;
  f.state='bounced';
  f.vy=-(11+Math.random()*3+Math.min(score*0.12,3));
  f.vx=(f.x<bed.x?-1:1)*(1.6+Math.random()*1.8);
  f.vr=(Math.random()-0.5)*0.25;
  bed.squash=1;
  sndBoing(Math.abs(f.vy));
  setScore(score+1);
  /* little star burst */
  for(var i=0;i<10;i++){
    particles.push({x:f.x,y:bed.topY-4,vx:(Math.random()-0.5)*4,vy:-Math.random()*3.4-0.6,life:1,s:Math.random()*3+2});
  }
  /* spawn next faller shortly after */
  var delay=420+Math.random()*380;
  setTimeout(function(){ if(state==='playing') spawnFaller(); }, delay);
  faller=null;
}

/* ============ MAIN LOOP ============ */
var last=0;
function loop(ts){
  requestAnimationFrame(loop);
  var dt=Math.min((ts-last)/16.7||1,3); last=ts;
  if(state==='paused'){ return; }
  frame++;

  ctx.clearRect(0,0,W,H);
  /* background */
  ctx.fillStyle='#f6f1e7'; ctx.fillRect(0,0,W,H);
  if(flashRed>0){ ctx.fillStyle='rgba(220,60,40,'+(flashRed*0.13)+')'; ctx.fillRect(0,0,W,H); flashRed-=0.03; }

  ctx.save();
  if(shake>0){ ctx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake); shake*=0.86; if(shake<0.3)shake=0; }

  /* floor strip */
  var floorY=H-46;
  ctx.fillStyle='#e3dac6'; ctx.fillRect(0,floorY,W,H-floorY);
  ctx.fillStyle='#cbbfa3'; ctx.fillRect(0,floorY,W,3);
  ctx.strokeStyle='rgba(160,145,115,.35)'; ctx.lineWidth=1;
  for(var fx2=floorY+14; fx2<H; fx2+=16){ ctx.beginPath(); ctx.moveTo(0,fx2); ctx.lineTo(W,fx2); ctx.stroke(); }

  /* splat mark on floor */
  if(splatMark){
    ctx.save(); ctx.translate(splatMark.x, floorY+16);
    ctx.fillStyle='rgba(40,40,40,.75)';
    ctx.beginPath(); ctx.ellipse(0,0,30,7,0,0,Math.PI*2); ctx.fill();
    ctx.font='20px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('💫',-20,-4); ctx.fillText('💫',22,-2);
    ctx.restore();
  }

  /* bed easing toward target */
  var prevX=bed.x;
  bed.x += (bed.targetX-bed.x)*Math.min(1,0.42*dt);
  bed.vx=bed.x-prevX;
  if(bed.squash>0) bed.squash=Math.max(0,bed.squash-0.09*dt);
  drawBed();

  /* dashed guide line from faller (like the video) */
  if(faller && faller.state==='falling' && state==='playing'){
    ctx.save();
    ctx.strokeStyle='rgba(60,60,60,.4)'; ctx.lineWidth=2; ctx.setLineDash([7,8]);
    ctx.beginPath(); ctx.moveTo(faller.x, faller.y+faller.r+52); ctx.lineTo(faller.x, bed.topY); ctx.stroke();
    ctx.restore();
  }

  /* faller physics */
  if(faller){
    var f=faller;
    if(f.state==='falling'){
      var grav=0.34+Math.min(score*0.012,0.22);
      f.vy+=grav*dt; f.y+=f.vy*dt; f.x+=f.vx*dt + Math.sin(frame/26+f.phase)*0.35*dt;
      f.rot=Math.sin(frame/20+f.phase)*0.14;
      if(f.x<30){f.x=30;f.vx=Math.abs(f.vx);} if(f.x>W-30){f.x=W-30;f.vx=-Math.abs(f.vx);}
      var feetY=drawStick(f);
      /* catch check: feet reach mattress top while over the bed */
      var overBed = f.x > bed.x-bed.w/2+14 && f.x < bed.x+bed.w/2-6;
      if(f.vy>0 && feetY>=bed.topY+4 && feetY<=bed.topY+34 && overBed){
        f.y -= (feetY-(bed.topY+4));
        bounceOff();
      } else if(feetY>=floorY+8){
        /* MISS */
        splatMark={x:f.x};
        shake=13; flashRed=1;
        faller=null;
        if(state==='playing') gameOver();
      }
    } else if(f.state==='bounced'){
      f.vy+=0.3*dt; f.y+=f.vy*dt; f.x+=f.vx*dt; f.rot+=f.vr*dt;
      drawStick(f);
      if(f.y<-90||f.x<-70||f.x>W+70){ /* gone — next already scheduled */ faller=null; }
    }
  }

  /* particles */
  for(var i=particles.length-1;i>=0;i--){
    var p=particles[i];
    p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=0.12*dt; p.life-=0.03*dt;
    if(p.life<=0){ particles.splice(i,1); continue; }
    ctx.save(); ctx.globalAlpha=Math.max(p.life,0);
    ctx.fillStyle='#e8a812';
    ctx.beginPath(); ctx.arc(p.x,p.y,p.s,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }

  ctx.restore();
}

/* ============ INPUT — drag the bed ============ */
var dragging=false, dragOffset=0;
function ptrX(e){ return e.touches ? e.touches[0].clientX : e.clientX; }
function onDown(e){
  audio();
  if(state!=='playing') return;
  dragging=true; dragOffset=bed.targetX-ptrX(e);
}
function onMove(e){
  if(!dragging||state!=='playing') return;
  var nx=ptrX(e)+dragOffset;
  bed.targetX=Math.max(bed.w/2-8, Math.min(W-bed.w/2+8, nx));
  if(e.cancelable) e.preventDefault();
}
function onUp(){ dragging=false; }
canvas.addEventListener('pointerdown',onDown);
window.addEventListener('pointermove',onMove,{passive:false});
window.addEventListener('pointerup',onUp);
canvas.addEventListener('touchstart',onDown,{passive:true});
window.addEventListener('touchmove',onMove,{passive:false});
window.addEventListener('touchend',onUp);
window.addEventListener('keydown',function(e){
  if(state!=='playing') return;
  if(e.key==='ArrowLeft'){ bed.targetX=Math.max(bed.w/2,bed.targetX-42); }
  if(e.key==='ArrowRight'){ bed.targetX=Math.min(W-bed.w/2,bed.targetX+42); }
  if(e.key===' '||e.key==='Escape'){ togglePause(); }
});

/* ============ CONTROLS ============ */
function togglePause(){
  if(state==='playing'){ state='paused'; pauseScreen.classList.remove('hidden'); }
  else if(state==='paused'){ state='playing'; pauseScreen.classList.add('hidden'); audio(); }
}
document.getElementById('pauseBtn').addEventListener('click',function(){ audio(); if(state==='playing'||state==='paused') togglePause(); });
document.getElementById('resumeBtn').addEventListener('click',togglePause);
document.getElementById('restartBtn2').addEventListener('click',startGame);
document.getElementById('startBtn').addEventListener('click',startGame);
document.getElementById('againBtn').addEventListener('click',startGame);
document.getElementById('soundBtn').addEventListener('click',function(){
  soundOn=!soundOn; this.textContent=soundOn?'🔊':'🔇';
  if(soundOn){ audio(); sndTick(); }
});

var fileInput=document.getElementById('fileInput');
function openPicker(){ fileInput.click(); }
document.getElementById('photoBtn').addEventListener('click',openPicker);
document.getElementById('photoBtn2').addEventListener('click',openPicker);
fileInput.addEventListener('change',function(){
  var file=this.files&&this.files[0]; if(!file) return;
  var url=URL.createObjectURL(file);
  var img=new Image();
  img.onload=function(){
    /* center-crop to square for a clean circular face */
    var s=Math.min(img.width,img.height);
    var c=document.createElement('canvas'); c.width=c.height=200;
    c.getContext('2d').drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,200,200);
    var cropped=new Image();
    cropped.onload=function(){
      faceImg=cropped;
      var pv=document.getElementById('facePreviewStart');
      pv.src=cropped.src; pv.style.display='block';
      sndBoing(6);
    };
    cropped.src=c.toDataURL();
  };
  img.src=url;
});

resize();
bed.x=W/2; bed.targetX=W/2;
requestAnimationFrame(loop);
})();
